# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">METALİK BAĞ: ELEKTRON DENİZİ MODELİ VE OLUŞUM ÖRÜNTÜSÜ (9.2.1)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">ELEKTRON DENİZİ MODELİ</text>\n  <circle cx="80" cy="115" r="18" fill="#dbeafe" stroke="#1d4ed8" stroke-width="2"/>\n  <text x="80" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">M+</text>\n  <circle cx="180" cy="115" r="18" fill="#dbeafe" stroke="#1d4ed8" stroke-width="2"/>\n  <text x="180" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">M+</text>\n  <circle cx="280" cy="115" r="18" fill="#dbeafe" stroke="#1d4ed8" stroke-width="2"/>\n  <text x="280" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">M+</text>\n  <circle cx="130" cy="95" r="6" fill="#fee2e2" stroke="#dc2626" stroke-width="1.5"/>\n  <text x="130" y="98" text-anchor="middle" font-size="9" font-weight="bold" fill="#b91c1c">e-</text>\n  <circle cx="230" cy="95" r="6" fill="#fee2e2" stroke="#dc2626" stroke-width="1.5"/>\n  <text x="230" y="98" text-anchor="middle" font-size="9" font-weight="bold" fill="#b91c1c">e-</text>\n  <circle cx="130" cy="135" r="6" fill="#fee2e2" stroke="#dc2626" stroke-width="1.5"/>\n  <text x="130" y="138" text-anchor="middle" font-size="9" font-weight="bold" fill="#b91c1c">e-</text>\n  <circle cx="230" cy="135" r="6" fill="#fee2e2" stroke="#dc2626" stroke-width="1.5"/>\n  <text x="230" y="138" text-anchor="middle" font-size="9" font-weight="bold" fill="#b91c1c">e-</text>\n  <text x="35" y="172" font-size="10.5" fill="#1e3a8a">• Metal atomlarının yoğunlaşmış fazda (katı/sıvı) düşük</text>\n  <text x="43" y="188" font-size="10.5" fill="#1e3a8a">iyonlaşma enerjili değerlik elektronları serbestçe dolaşarak</text>\n  <text x="43" y="204" font-size="10.5" font-weight="bold" fill="#b91c1c">negatif yüklü \'elektron denizi\' oluşturur.</text>\n  <text x="35" y="224" font-size="10.5" font-weight="bold" fill="#1e40af">• Katyonlar (M+) ile e- denizi arasındaki elektrostatik çekimdir.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">METALİK BAĞ GÜCÜNÜ ETKİLEYEN ETMENLER</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#14532d">1. Değerlik Elektron Sayısı (Doğru Orantılı):</text>\n  <text x="383" y="114" font-size="10.5" fill="#166534">Aynı periyotta soldan sağa gidildikçe değerlik elektron</text>\n  <text x="383" y="130" font-size="10.5" fill="#166534">sayısı artar → Metalik bağ kuvveti ve erime noktası ARTAR.</text>\n  <text x="383" y="148" font-size="10.5" font-weight="bold" fill="#15803d">Örnek (3. Periyot): 11Na (1A) &lt; 12Mg (2A) &lt; 13Al (3A)</text>\n  <text x="375" y="176" font-size="11" font-weight="bold" fill="#14532d">2. Atom Yarıçapı / Hacmi (Ters Orantılı):</text>\n  <text x="383" y="194" font-size="10.5" fill="#166534">Aynı grupta yukarıdan aşağıya inildikçe atom yarıçapı</text>\n  <text x="383" y="210" font-size="10.5" fill="#166534">büyür → Metalik bağ kuvveti ve erime noktası AZALIR.</text>\n  <text x="383" y="226" font-size="10.5" font-weight="bold" fill="#b91c1c">Örnek (1A Grubu): 3Li &gt; 11Na &gt; 19K</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">METALİK BAĞIN METALLERİN FİZİKSEL ÖZELLİKLERİNE ETKİSİ</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b45309">1. ISI VE ELEKTRİK İLETKENLİĞİ</text>\n  <text x="32" y="96" font-size="10.5" fill="#78350f">• Elektron denizindeki serbest</text>\n  <text x="32" y="112" font-size="10.5" fill="#78350f">hareketli değerlik elektronları</text>\n  <text x="32" y="128" font-size="10.5" fill="#78350f">sayesinde metaller katı ve sıvı</text>\n  <text x="32" y="144" font-size="10.5" fill="#78350f">hâlde elektriği ve ısıyı çok iyi</text>\n  <text x="32" y="160" font-size="10.5" fill="#78350f">iletir.</text>\n  <text x="32" y="190" font-size="10" font-weight="bold" fill="#b91c1c">• Dikkat: Metallerin elektriği</text>\n  <text x="32" y="206" font-size="10" font-weight="bold" fill="#b91c1c">iletmesi FİZİKSEL bir olaydır!</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#7e22ce">2. TEL VE LEVHA HÂLİNE GELME</text>\n  <text x="257" y="96" font-size="10.5" fill="#581c87">• Metale kuvvet uygulandığında</text>\n  <text x="257" y="112" font-size="10.5" fill="#581c87">(dövüldüğünde) pozitif metal</text>\n  <text x="257" y="128" font-size="10.5" fill="#581c87">katyonları elektron denizi içinde</text>\n  <text x="257" y="144" font-size="10.5" fill="#581c87">birbiri üzerinden kayar; bağ</text>\n  <text x="257" y="160" font-size="10.5" fill="#581c87">kopmaz ve kristal kırılmaz.</text>\n  <text x="257" y="190" font-size="10" font-weight="bold" fill="#6b21a8">• Bu sayede metaller eğilip</text>\n  <text x="257" y="206" font-size="10" font-weight="bold" fill="#6b21a8">bükülebilir, haddelenebilir.</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">3. METALİK PARLAKLIK &amp; ALAŞIM</text>\n  <text x="482" y="96" font-size="10.5" fill="#1e3a8a">• Serbest elektronlar üzerine</text>\n  <text x="482" y="112" font-size="10.5" fill="#1e3a8a">düşen ışığı soğurup uyarılır ve</text>\n  <text x="482" y="128" font-size="10.5" fill="#1e3a8a">eski hâline dönerken ışığı geri</text>\n  <text x="482" y="144" font-size="10.5" fill="#1e3a8a">yansıtır → Metalik parlaklık.</text>\n  <text x="482" y="174" font-size="10" font-weight="bold" fill="#15803d">• Farklı metallerin eritilerek</text>\n  <text x="482" y="190" font-size="10" font-weight="bold" fill="#15803d">karıştırılmasıyla oluşan</text>\n  <text x="482" y="206" font-size="10" font-weight="bold" fill="#15803d">homojen karışımlara ALAŞIM</text>\n  <text x="482" y="222" font-size="10" font-weight="bold" fill="#15803d">(tunç, pirinç, lehim) denir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İYONİK BAĞA GİRİŞ: KATYON - ANYON ETKİLEŞİMİ (9.2.2)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">ELEKTRON ALIŞVERİŞİ VE İYON OLUŞUMU</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#881337">• Metal Atomu (Düşük İE) → Elektron VERİR → Katyon (+)</text>\n  <text x="43" y="114" font-size="10.5" fill="#9f1239">Örnek: 11Na (2-8-1) → Na+ (2-8) + e-</text>\n  <text x="35" y="142" font-size="11" font-weight="bold" fill="#881337">• Ametal Atomu (Yüksek EN) → Elektron ALIR → Anyon (-)</text>\n  <text x="43" y="160" font-size="10.5" fill="#9f1239">Örnek: 17Cl (2-8-7) + e- → Cl- (2-8-8)</text>\n  <text x="35" y="190" font-size="11" font-weight="bold" fill="#b91c1c">• İyonik Bağ: Na+ ve Cl- zıt yüklü iyonların birbirini</text>\n  <text x="43" y="208" font-size="11" font-weight="bold" fill="#b91c1c">elektrostatik çekim kuvvetiyle çekmesiyle oluşur.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">METALİK BAĞ İLE İYONİK BAĞ KARŞILAŞTIRMASI</text>\n  <text x="375" y="96" font-size="10.5" font-weight="bold" fill="#14532d">• Tanecik Türü:</text>\n  <text x="383" y="112" font-size="10" fill="#166534">Metalik bağda: Metal katyonları + serbest elektron denizi.</text>\n  <text x="383" y="128" font-size="10" fill="#166534">İyonik bağda: Metal katyonu (+) + Ametal anyonu (-).</text>\n  <text x="375" y="154" font-size="10.5" font-weight="bold" fill="#14532d">• Elektrik İletkenliği:</text>\n  <text x="383" y="170" font-size="10" fill="#166534">Metaller katı ve sıvı hâlde elektron hareketiyle iletir;</text>\n  <text x="383" y="186" font-size="10" font-weight="bold" fill="#b91c1c">İyonik katılar elektriği İLETMEZ, sıvı ve sulu çözeltisi</text>\n  <text x="383" y="202" font-size="10" font-weight="bold" fill="#b91c1c">iyon hareketiyle (kimyasal olarak) iletir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
